{"implementation":"def solve(case):
    def is_int(value):
        return type(value) is int

    if not isinstance(case, dict):
        raise ValueError("case must be an object")
    if "segments" not in case or "budget" not in case:
        raise ValueError("missing required case field")
    segments = case["segments"]
    budget = case["budget"]
    if not isinstance(segments, list) or not is_int(budget) or budget < 0:
        raise ValueError("invalid case fields")

    names = []
    importances = []
    minimums = []
    capacities = []
    seen = set()
    for segment in segments:
        if not isinstance(segment, dict):
            raise ValueError("segment must be an object")
        for field in ("name", "importance", "minimum", "capacity"):
            if field not in segment:
                raise ValueError("missing required segment field")
        name = segment["name"]
        importance = segment["importance"]
        minimum = segment["minimum"]
        capacity = segment["capacity"]
        if not isinstance(name, str):
            raise ValueError("segment name must be a string")
        if name in seen:
            raise ValueError("duplicate segment name")
        if not is_int(importance) or not is_int(minimum) or not is_int(capacity):
            raise ValueError("segment quantities must be integers")
        if minimum < 0 or capacity < minimum:
            raise ValueError("invalid segment bounds")
        seen.add(name)
        names.append(name)
        importances.append(importance)
        minimums.append(minimum)
        capacities.append(capacity)

    allocations = list(minimums)
    quota_sum = sum(allocations)
    capacity_sum = sum(capacities)
    if budget < quota_sum or budget > capacity_sum:
        raise ValueError("infeasible budget")

    remaining = budget - quota_sum
    while remaining:
        best = None
        for index in range(len(allocations)):
            if allocations[index] >= capacities[index]:
                continue
            if best is None:
                best = index
                continue
            left = importances[index] * (allocations[best] + 1)
            right = importances[best] * (allocations[index] + 1)
            if left > right:
                best = index
        if best is None:
            raise ValueError("infeasible budget")
        allocations[best] += 1
        remaining -= 1

    by_name = {names[index]: allocations[index] for index in range(len(names))}
    total = sum(allocations)
    return {"allocations": allocations, "by_name": by_name, "total": total}
"}
